-- Run after fixture + proposed 0089 on isolated DB. Rollback all player actions.
BEGIN;
CREATE FUNCTION pg_temp.assert_true(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'ECHEC : %',label; END IF; RAISE NOTICE 'OK : %',label; END $$;
CREATE FUNCTION pg_temp.reject(q text,expected text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
  BEGIN EXECUTE q; EXCEPTION WHEN OTHERS THEN IF position(expected in SQLERRM)>0 THEN RAISE NOTICE 'OK refus : %',expected; RETURN; ELSE RAISE; END IF; END;
  RAISE EXCEPTION 'Action acceptée à tort : %',expected;
END $$;
SELECT set_config('test.uid','10000000-0000-0000-0000-000000000001',true);
SELECT pg_temp.assert_true(jsonb_array_length(public.home_furnishing_state()->'homes')=2,'Deux logements possédés seulement');
SELECT pg_temp.assert_true(jsonb_array_length(public.home_furnishing_state()->'furniture')=2,'Deux objets possédés seulement, aucun offert');
SELECT pg_temp.reject($q$SELECT public.home_furnishing_save('20000000-0000-0000-0000-000000000009',0,'["A"]','[]',gen_random_uuid())$q$,'Logement non possédé');
SELECT pg_temp.reject($q$SELECT public.home_furnishing_save('20000000-0000-0000-0000-000000000001',0,'["A","B"]','[{"asset_id":"30000000-0000-0000-0000-000000000003","room":0,"x":0,"y":0,"rotation":0}]',gen_random_uuid())$q$,'Objet non possédé');
SELECT pg_temp.reject($q$SELECT public.home_furnishing_save('20000000-0000-0000-0000-000000000001',0,'["A","B"]','[{"asset_id":"30000000-0000-0000-0000-000000000001","room":0,"x":0,"y":0,"rotation":0},{"asset_id":"30000000-0000-0000-0000-000000000001","room":0,"x":4,"y":0,"rotation":0}]',gen_random_uuid())$q$,'Objet placé deux fois');
SELECT pg_temp.reject($q$SELECT public.home_furnishing_save('20000000-0000-0000-0000-000000000001',0,'["A","B"]','[{"asset_id":"30000000-0000-0000-0000-000000000001","room":0,"x":0,"y":0,"rotation":0},{"asset_id":"30000000-0000-0000-0000-000000000002","room":0,"x":0,"y":0,"rotation":0}]',gen_random_uuid())$q$,'Objets superposés');
SELECT pg_temp.reject($q$SELECT public.home_furnishing_save('20000000-0000-0000-0000-000000000001',0,'["A","B"]','[{"asset_id":"30000000-0000-0000-0000-000000000001","room":0,"x":7,"y":0,"rotation":0}]',gen_random_uuid())$q$,'Objet hors de la pièce');
SELECT pg_temp.reject($q$SELECT public.home_furnishing_save('20000000-0000-0000-0000-000000000001',0,'["A","B"]','[{"asset_id":"30000000-0000-0000-0000-000000000001","room":2,"x":0,"y":0,"rotation":0}]',gen_random_uuid())$q$,'Pièce ou rotation invalide');
SELECT pg_temp.reject($q$SELECT public.home_furnishing_save('20000000-0000-0000-0000-000000000001',0,'["A","B"]','[{"asset_id":"30000000-0000-0000-0000-000000000001","room":0,"x":0,"y":0,"rotation":45}]',gen_random_uuid())$q$,'Pièce ou rotation invalide');
SELECT pg_temp.reject($q$SELECT public.home_furnishing_save('20000000-0000-0000-0000-000000000001',0,'["A","B"]','[{"asset_id":"30000000-0000-0000-0000-000000000001","room":0,"x":0.5,"y":0,"rotation":0}]',gen_random_uuid())$q$,'Position invalide');
SELECT pg_temp.assert_true((public.home_furnishing_save('20000000-0000-0000-0000-000000000001',0,'["Salon","Pièce 2"]','[{"asset_id":"30000000-0000-0000-0000-000000000001","room":0,"x":1,"y":1,"rotation":90}]','40000000-0000-0000-0000-000000000001')->>'version')::integer=1,'Sauvegarde version 1');
SELECT pg_temp.assert_true((public.home_furnishing_save('20000000-0000-0000-0000-000000000001',0,'["Salon","Pièce 2"]','[{"asset_id":"30000000-0000-0000-0000-000000000001","room":0,"x":1,"y":1,"rotation":90}]','40000000-0000-0000-0000-000000000001')->>'already')::boolean,'Double sauvegarde idempotente');
SELECT pg_temp.reject($q$SELECT public.home_furnishing_save('20000000-0000-0000-0000-000000000001',0,'["A","B"]','[]',gen_random_uuid())$q$,'Aménagement modifié ailleurs');
SELECT pg_temp.reject($q$SELECT public.home_furnishing_save('20000000-0000-0000-0000-000000000002',0,'["A"]','[{"asset_id":"30000000-0000-0000-0000-000000000001","room":0,"x":0,"y":0,"rotation":0}]',gen_random_uuid())$q$,'Objet placé dans un autre logement');
SELECT pg_temp.assert_true((SELECT room_names->>0='Salon' FROM public.home_layouts),'Nom enregistré');
SELECT pg_temp.assert_true((SELECT x=1 AND y=1 AND rotation=90 FROM public.home_placements),'Position et rotation relues');
SELECT pg_temp.assert_true((SELECT sum(purchase_price)=150887 FROM public.personal_assets),'Valeurs du patrimoine inchangées');
SET LOCAL ROLE authenticated;
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM public.home_placements),'Lecture propriétaire autorisée');
SELECT pg_temp.reject($q$DELETE FROM public.home_placements$q$,'permission denied');
SELECT set_config('test.uid','10000000-0000-0000-0000-000000000002',true);
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.home_placements),'Aménagement autre joueur privé');
SELECT pg_temp.assert_true(jsonb_array_length(public.home_furnishing_state()->'homes')=0,'RPC autre joueur ne voit pas les logements');
RESET ROLE;
SELECT set_config('test.uid','10000000-0000-0000-0000-000000000001',true);
SELECT public.home_furnishing_save('20000000-0000-0000-0000-000000000001',1,'["Salon","Pièce 2"]','[]',gen_random_uuid());
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.home_placements),'Rangement enlève le placement');
SELECT pg_temp.assert_true((SELECT count(*)=5 FROM public.personal_assets),'Rangement conserve les objets');
SELECT public.home_furnishing_save('20000000-0000-0000-0000-000000000001',2,'["Salon","Pièce 2"]','[{"asset_id":"30000000-0000-0000-0000-000000000001","room":1,"x":0,"y":0,"rotation":0}]',gen_random_uuid());
DELETE FROM public.personal_assets WHERE id='30000000-0000-0000-0000-000000000001';
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.home_placements),'Revente objet supprime son placement');
SELECT public.home_furnishing_save('20000000-0000-0000-0000-000000000001',3,'["Salon","Pièce 2"]','[{"asset_id":"30000000-0000-0000-0000-000000000002","room":0,"x":0,"y":0,"rotation":0}]',gen_random_uuid());
DELETE FROM public.personal_assets WHERE id='20000000-0000-0000-0000-000000000001';
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.home_placements),'Revente logement supprime les placements');
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM public.personal_assets WHERE id='30000000-0000-0000-0000-000000000002'),'Revente logement conserve son mobilier');
SELECT set_config('test.uid','',true);
SELECT pg_temp.reject($q$SELECT public.home_furnishing_state()$q$,'Non connecté');
SELECT pg_temp.assert_true(NOT has_function_privilege('anon','public.home_furnishing_save(uuid,integer,jsonb,jsonb,uuid)','EXECUTE'),'Anonyme sans droit de sauvegarde');
ROLLBACK;
